class Solution {
public:
    int getLucky(string s, int k) {
        int sum = 0;
        for (char c : s) {
            int val = c - 'a' + 1;
            while (val > 0) {
                sum += val % 10;
                val /= 10;
            }
        }
        for (int i = 1; i < k; i++) {
            int next = 0;
            while (sum > 0) {
                next += sum % 10;
                sum /= 10;
            }
            sum = next;
        }
        return sum;
    }
};
